-- Backfill example song for existing users
-- Run in Supabase Dashboard > SQL Editor > New Query

-- Remove any previously-seeded songs for these users so we can re-insert correctly
DELETE FROM songs
WHERE title = 'Knockin'' on Heaven''s Door'
  AND user_id IN (SELECT id FROM auth.users WHERE email IN ('mark.hazlewood@hazydesigns.com'));

INSERT INTO songs (user_id, title, document, annotations, is_locked)
