  $ann${"ann-seed-1":{"id":"ann-seed-1","type":"chord","value":"G","lineId":"line-seed-1","charOffset":0,"charOffsetEnd":5},"ann-seed-2":{"id":"ann-seed-2","type":"chord","value":"D","lineId":"line-seed-1","charOffset":6,"charOffsetEnd":10},"ann-seed-3":{"id":"ann-seed-3","type":"chord","value":"Am","lineId":"line-seed-1","charOffset":29,"charOffsetEnd":31},"ann-seed-4":{"id":"ann-seed-4","type":"chord","value":"G","lineId":"line-seed-2","charOffset":0,"charOffsetEnd":1},"ann-seed-5":{"id":"ann-seed-5","type":"chord","value":"D","lineId":"line-seed-2","charOffset":8,"charOffsetEnd":11},"ann-seed-6":{"id":"ann-seed-6","type":"chord","value":"C","lineId":"line-seed-2","charOffset":15,"charOffsetEnd":22},"ann-seed-7":{"id":"ann-seed-7","type":"chord","value":"G","lineId":"line-seed-3","charOffset":0,"charOffsetEnd":4},"ann-seed-8":{"id":"ann-seed-8","type":"chord","value":"D","lineId":"line-seed-3","charOffset":13,"charOffsetEnd":18},"ann-seed-9":{"id":"ann-seed-9","type":"chord","value":"Am","lineId":"line-seed-3","charOffset":31,"charOffsetEnd":34},"ann-seed-10":{"id":"ann-seed-10","type":"chord","value":"G","lineId":"line-seed-4","charOffset":2,"charOffsetEnd":6},"ann-seed-11":{"id":"ann-seed-11","type":"chord","value":"D","lineId":"line-seed-4","charOffset":11,"charOffsetEnd":19},"ann-seed-12":{"id":"ann-seed-12","type":"chord","value":"C","lineId":"line-seed-4","charOffset":32,"charOffsetEnd":36},"ann-seed-13":{"id":"ann-seed-13","type":"chord","value":"G","lineId":"line-seed-6","charOffset":0,"charOffsetEnd":6},"ann-seed-14":{"id":"ann-seed-14","type":"chord","value":"D","lineId":"line-seed-6","charOffset":14,"charOffsetEnd":22},"ann-seed-15":{"id":"ann-seed-15","type":"chord","value":"C","lineId":"line-seed-6","charOffset":35,"charOffsetEnd":39},"ann-seed-16":{"id":"ann-seed-16","type":"right-side","style":"default","value":"Click on any word, then select Chord to add chord annotations like these","lineId":"line-seed-1","charOffset":6},"ann-seed-17":{"id":"ann-seed-17","type":"right-side","style":"default","value":"Select a range of text, then select Note in to create a text note or paste an image (cmd/ctrl+v)","lineId":"line-seed-9","charOffset":7},"ann-seed-18":{"id":"ann-seed-18","type":"image","lineId":"line-seed-6","url":"https://aukdulztojapsiocohna.supabase.co/storage/v1/object/public/annotation-images/example-notation.png","charOffset":35}}$ann$::jsonb,
